// Generated by tools/Site/import-tutorial.mjs from the completed tutorial.
export const tutorial = {"title":"Phantom Fudge - The Complete Tutorial","duration":2297.766666666667,"chapters":[{"id":"welcome","title":"Welcome and important boundaries","start":0,"end":59.5},{"id":"installation","title":"Install, launch, update and remove","start":59.5,"end":204.96666666666667},{"id":"workspace","title":"Understand the workspace","start":204.96666666666667,"end":335.96666666666664},{"id":"audio","title":"Select audio without scrolling","start":335.96666666666664,"end":505.5},{"id":"transcription","title":"Start, read and stop transcription","start":505.5,"end":586.4333333333333},{"id":"questions","title":"Build and review a question","start":586.4333333333333,"end":772.1},{"id":"providers","title":"Set up an optional answer provider","start":772.1,"end":955.0666666666667},{"id":"answers","title":"Ask, read, copy and cancel","start":955.0666666666667,"end":1049.2333333333333},{"id":"followups","title":"Follow up with the previous answer","start":1049.2333333333333,"end":1126.7},{"id":"clarification","title":"Clarify a question before answering","start":1126.7,"end":1276.5333333333333},{"id":"cancel-errors","title":"Cancel and recover from answer errors","start":1276.5333333333333,"end":1337.9333333333334},{"id":"notes","title":"Speaker notes and local files","start":1337.9333333333334,"end":1570.5666666666666},{"id":"export","title":"Export and clear the transcript","start":1570.5666666666666,"end":1631.7},{"id":"keyboard","title":"Keyboard-first controls","start":1631.7,"end":2039.4333333333334},{"id":"cover","title":"Cover, hide, recovery and exit","start":2039.4333333333334,"end":2297.766666666667}],"cues":[{"start":0.44999999999999996,"end":3.83,"text":"Welcome to the complete Phantom Fudge tutorial."},{"start":3.83,"end":9.7,"text":"We will walk through audio, notes, questions, answers, follow-ups,"},{"start":9.7,"end":13.299999999999999,"text":"keyboard controls, and day-to-day recovery."},{"start":13.299999999999999,"end":17.795,"text":"Use the chapter list beside the video to jump directly to any lesson."},{"start":18.916666666666664,"end":23.086666666666666,"text":"This is a scripted demonstration of the real Windows interface."},{"start":23.086666666666666,"end":27.606666666666662,"text":"Transcript text, device names, and answers are samples."},{"start":27.606666666666662,"end":31.571666666666665,"text":"No meeting, microphone, or remote model is used."},{"start":31.571666666666665,"end":35.16166666666666,"text":"Click guides show scripted control activations."},{"start":35.16166666666666,"end":37.26166666666667,"text":"Native file pickers are omitted;"},{"start":37.26166666666667,"end":40.986666666666665,"text":"sample files and clipboard output stay isolated."},{"start":42.11666666666667,"end":45.75666666666666,"text":"The current source includes the Previous answer toggle."},{"start":45.75666666666666,"end":51.06166666666667,"text":"The published version zero point two preview one does not include that newer feature."},{"start":51.06166666666667,"end":56.55166666666666,"text":"This tutorial does not update the published installer, and it does not prove that every screen-sharing"},{"start":56.55166666666666,"end":58.83166666666666,"text":"product excludes the window."},{"start":59.95,"end":65.4,"text":"On the private GitHub release page, download the Windows eleven, sixty-four-bit Setup"},{"start":65.4,"end":69.045,"text":"file. Check the published checksum."},{"start":69.045,"end":74.58,"text":"Open Setup, review the unsigned-preview warning, and follow the installer."},{"start":74.58,"end":79.235,"text":"Finish and close Setup, then launch Phantom Fudge from Start."},{"start":79.235,"end":81.85,"text":"Setup does not launch it for you."},{"start":82.95,"end":85.235,"text":"The installer is per-user."},{"start":85.235,"end":91.16,"text":"It bundles the desktop runtime, local speech runtime, and speech models."},{"start":91.16,"end":97.015,"text":"You do not need developer tools, system Python, or Docker for normal installed use."},{"start":97.015,"end":103.075,"text":"Answer providers are separate: installing Phantom Fudge does not configure an AI account."},{"start":104.18333333333334,"end":109.49833333333333,"text":"For the portable package, extract the entire archive and open Phantom Fudge dot Launcher in"},{"start":109.49833333333333,"end":113.96333333333334,"text":"its launcher folder. Keep the whole extraction together."},{"start":113.96333333333334,"end":119.45833333333333,"text":"For the latest source, follow the prerequisites and use the repository launcher."},{"start":119.45833333333333,"end":123.31833333333333,"text":"That source route includes the newer previous-answer feature."},{"start":124.45,"end":130.445,"text":"Source development uses PowerShell seven point two or later, Python three point thirteen,"},{"start":130.445,"end":135.055,"text":"and the .NET ten SDK selected by global dot JSON."},{"start":135.055,"end":139.45,"text":"Follow the Desktop Runtime prerequisite for development builds."},{"start":139.45,"end":145.21,"text":"Initialize Transcription prepares dependencies and models before the source launcher runs."},{"start":145.21,"end":149.36,"text":"Installed normal use does not require these developer tools."},{"start":150.48333333333332,"end":156.52333333333334,"text":"If speech startup fails, the installed launcher offers Open notes without transcription."},{"start":156.52333333333334,"end":159.25833333333333,"text":"The source equivalent is Notes Only."},{"start":159.25833333333333,"end":161.44333333333333,"text":"This skips speech-service startup;"},{"start":161.44333333333333,"end":166.97333333333333,"text":"it does not disable an already configured answer provider or stop an existing service."},{"start":168.08333333333331,"end":173.39333333333332,"text":"Before an update, save notes, export anything you need, and close the app with"},{"start":173.39333333333332,"end":177.31333333333333,"text":"X. Then run the newer versioned Setup."},{"start":177.31333333333333,"end":181.36833333333334,"text":"The installer supports install, repair, and update;"},{"start":181.36833333333334,"end":185.77833333333334,"text":"an app that has not finished shutting down is not a successful update."},{"start":186.88333333333333,"end":192.44833333333332,"text":"To remove the installed app, open Windows Settings, Apps, Installed apps,"},{"start":192.44833333333332,"end":195.79333333333335,"text":"then find Phantom Fudge and choose Uninstall."},{"start":195.79333333333335,"end":199.71333333333334,"text":"External notes, exports, and settings are retained."},{"start":199.71333333333334,"end":204.28833333333333,"text":"Uninstalling the program is not a secure erase of those separate files."},{"start":205.41666666666666,"end":209.86666666666667,"text":"The app starts in presentation mode, with notes collapsed."},{"start":209.86666666666667,"end":214.69666666666666,"text":"The transcript is on the left; your question and answer are on the right."},{"start":214.69666666666666,"end":220.09666666666666,"text":"Both audio sources are selected by default, but nothing is recorded until you explicitly press"},{"start":220.09666666666666,"end":221.31166666666667,"text":"Start."},{"start":222.41666666666666,"end":226.21666666666667,"text":"Click Hide Q slash A to collapse the question pane."},{"start":226.21666666666667,"end":230.76666666666668,"text":"It also cancels an active answer and stops provider preparation."},{"start":230.76666666666668,"end":234.19666666666666,"text":"Your transcript and saved files are not erased."},{"start":235.31666666666666,"end":239.4766666666667,"text":"Click Show Q slash A to bring the question workspace back."},{"start":239.4766666666667,"end":242.08166666666668,"text":"Wide windows use side-by-side panes;"},{"start":242.08166666666668,"end":244.61166666666668,"text":"narrower windows adapt the layout."},{"start":245.71666666666667,"end":250.61666666666667,"text":"Drag the empty title-bar grip to move the window, not the text area."},{"start":250.61666666666667,"end":253.4766666666667,"text":"Drag an edge or corner to resize it."},{"start":253.4766666666667,"end":256.3066666666667,"text":"Keep the controls comfortably readable."},{"start":256.3066666666667,"end":258.7216666666667,"text":"There is no ordinary taskbar button;"},{"start":258.7216666666667,"end":263.06666666666666,"text":"use the recovery shortcut or relaunch the app if you lose the window."},{"start":264.18333333333334,"end":266.40833333333336,"text":"Here the window is narrowed."},{"start":266.40833333333336,"end":272.68833333333333,"text":"The actual interface rearranges itself instead of placing every control in a scrolling outer panel."},{"start":272.68833333333333,"end":276.0733333333333,"text":"Long text can still scroll inside its own reader."},{"start":277.18333333333334,"end":281.79333333333335,"text":"Use a wider window when you want the transcript and answer visible together."},{"start":281.79333333333335,"end":285.2683333333334,"text":"A wider layout is helpful for the first walkthrough."},{"start":286.3833333333333,"end":290.3283333333333,"text":"Click the sun and theme-name button to switch to Harbor Daylight."},{"start":290.3283333333333,"end":292.48833333333334,"text":"The next theme is named on the button;"},{"start":292.48833333333334,"end":295.48333333333335,"text":"your transcript and question are preserved."},{"start":296.5833333333333,"end":300.85333333333335,"text":"Click Plain B slash W for the neutral black-and-white look."},{"start":300.85333333333335,"end":304.11833333333334,"text":"It is a theme reset, not a data reset."},{"start":305.25,"end":308.88,"text":"Click the theme button again to return to Deep Sea Foam."},{"start":308.88,"end":312.71500000000003,"text":"Choose whichever theme gives you the clearest reading contrast."},{"start":313.81666666666666,"end":318.63166666666666,"text":"Drag Background toward ten percent to make the background more transparent."},{"start":318.63166666666666,"end":320.76666666666665,"text":"The text stays solid."},{"start":320.76666666666665,"end":325.1066666666667,"text":"This is not click-through, and it does not make the process hidden."},{"start":326.21666666666664,"end":331.46666666666664,"text":"Drag Background back toward one hundred percent when the material behind the window makes text difficult"},{"start":331.46666666666664,"end":335.28666666666663,"text":"to read. This setting is for the current session."},{"start":336.41666666666663,"end":338.45666666666665,"text":"Click Audio setup."},{"start":338.45666666666665,"end":343.78666666666663,"text":"Opening it closes Q slash A and cancels its answer or preparation, but does not stop"},{"start":343.78666666666663,"end":347.9216666666666,"text":"audio. Stop before changing devices."},{"start":347.9216666666666,"end":350.03666666666663,"text":"These cards use sample names;"},{"start":350.03666666666663,"end":353.65666666666664,"text":"on your machine they show the available Windows devices."},{"start":354.7833333333333,"end":359.8533333333333,"text":"Click Computer to transcribe the sound played by your selected output device."},{"start":359.8533333333333,"end":365.3633333333333,"text":"This can include other applications and microphone sidetone, not just the meeting."},{"start":366.48333333333335,"end":372.11833333333334,"text":"Click the card for the device where you actually hear the meeting, such as your headphones."},{"start":372.11833333333334,"end":375.95833333333337,"text":"The highlighted border and filled dot identify the selection."},{"start":377.0833333333333,"end":380.72833333333335,"text":"Click Mic if you only want microphone transcription."},{"start":380.72833333333335,"end":385.47833333333335,"text":"This is a separate source; the app does not read meeting chat messages."},{"start":386.5833333333333,"end":389.5133333333333,"text":"Choose the microphone you intend to use."},{"start":389.5133333333333,"end":395.0983333333333,"text":"If that selected input fails during capture, the session stops rather than silently substituting"},{"start":395.0983333333333,"end":401.3333333333333,"text":"another microphone. After an explicit Refresh, check the selected card again."},{"start":402.45,"end":405.59,"text":"Click Both to use Computer and Mic together."},{"start":405.59,"end":409.25,"text":"Their transcript lines keep separate source labels."},{"start":409.25,"end":414.545,"text":"Those labels identify the input track, not individual people in the meeting."},{"start":415.65,"end":419.78999999999996,"text":"While stopped, click Refresh after connecting hardware."},{"start":419.78999999999996,"end":423.695,"text":"Either Refresh button rediscovers both device lists."},{"start":423.695,"end":427.115,"text":"The previous selection stays if its device still exists;"},{"start":427.115,"end":430.52,"text":"otherwise the first available device is selected."},{"start":430.52,"end":433.145,"text":"Recheck both cards before Start."},{"start":434.25,"end":439.23,"text":"For a machine with many outputs, the card layout adds page arrows."},{"start":439.23,"end":444.345,"text":"This sample list shows that behavior without changing any Windows audio settings."},{"start":445.45,"end":448.55,"text":"Click the right arrow to see the next page."},{"start":448.55,"end":453.6,"text":"The page label also tells you which page contains the currently selected device."},{"start":454.71666666666664,"end":457.26166666666666,"text":"Click the left arrow to go back."},{"start":457.26166666666666,"end":461.19666666666666,"text":"Changing pages does not itself select a different device."},{"start":462.31666666666666,"end":465.7266666666667,"text":"We will return to the small sample device list."},{"start":465.7266666666667,"end":470.4266666666667,"text":"In normal use, select your intended card before leaving setup."},{"start":471.55,"end":476.18,"text":"Click Service setup to see the session-only local service token field."},{"start":476.18,"end":479.14500000000004,"text":"Normally the launcher supplies this for you."},{"start":479.14500000000004,"end":481.49,"text":"Edit mode enables manual entry;"},{"start":481.49,"end":486.02000000000004,"text":"never publish or paste your actual token into a tutorial or chat."},{"start":487.15,"end":491.06,"text":"Click Close service setup to put the advanced field away."},{"start":491.06,"end":493.805,"text":"Native local recognition is the normal path;"},{"start":493.805,"end":496.58,"text":"Docker is not a startup requirement."},{"start":497.68333333333334,"end":500.55833333333334,"text":"Click Done to return to the workspace."},{"start":500.55833333333334,"end":504.8283333333334,"text":"Choosing devices and closing setup do not begin transcription."},{"start":505.95,"end":511.3,"text":"Click Start. In normal use this starts the selected audio inputs."},{"start":511.3,"end":514.565,"text":"Here it starts only the labelled sample stream."},{"start":514.565,"end":519.27,"text":"The red dot means selected inputs are running, not merely selected."},{"start":520.3833333333333,"end":524.6183333333332,"text":"A partial line appears while recognition is still in progress."},{"start":524.6183333333332,"end":527.5433333333333,"text":"It can change as more speech arrives."},{"start":527.5433333333333,"end":532.0933333333332,"text":"Treat it as provisional, especially before sending it as a question."},{"start":533.2166666666667,"end":537.9366666666666,"text":"The completed line moves into the transcript history with its Computer label."},{"start":537.9366666666666,"end":542.9266666666666,"text":"Local recognition is fallible, so review important words and names."},{"start":544.0500000000001,"end":546.88,"text":"A microphone line is labelled Mic."},{"start":546.88,"end":550.705,"text":"Computer and Mic stay separate even when Both is selected."},{"start":550.705,"end":554.97,"text":"Headphones help reduce speaker echo that a microphone might pick up."},{"start":556.0833333333334,"end":559.2233333333334,"text":"New lines continue arriving while you read."},{"start":559.2233333333334,"end":564.0783333333334,"text":"The app does not automatically send the entire meeting to an answer provider."},{"start":564.0783333333334,"end":566.6283333333333,"text":"You choose the text to ask about."},{"start":567.75,"end":571.255,"text":"Click Stop to stop the selected audio inputs."},{"start":571.255,"end":575.66,"text":"Wait for final draining and the stopped state before changing devices."},{"start":575.66,"end":580.885,"text":"Stop does not cancel a separate answer, and an accepted final transcript line may still"},{"start":580.885,"end":585.76,"text":"arrive while draining. This workflow does not save raw audio."},{"start":586.8833333333333,"end":589.5433333333333,"text":"Click the first transcript line."},{"start":589.5433333333333,"end":594.5983333333332,"text":"Its text becomes a local question draft, and question editing opens."},{"start":594.5983333333332,"end":597.0583333333333,"text":"A click does not send anything."},{"start":598.1833333333334,"end":600.8733333333333,"text":"Click the microphone line as well."},{"start":600.8733333333333,"end":606.5883333333334,"text":"Multiple lines combine in transcript order, not in the order you happened to click them."},{"start":607.7166666666667,"end":611.2816666666666,"text":"Click the selected microphone line again to remove it."},{"start":611.2816666666666,"end":615.9666666666667,"text":"You can build a useful question without copying unrelated meeting context."},{"start":617.0833333333334,"end":623.4483333333334,"text":"Select the microphone line again because it contains the useful instruction to keep the answer concise."},{"start":623.4483333333334,"end":626.3283333333334,"text":"Review the assembled draft before editing."},{"start":627.45,"end":631.16,"text":"Edit the draft into the exact question you want answered."},{"start":631.16,"end":635.83,"text":"Typing here is independent of Notes Edit and does not stop transcription."},{"start":636.95,"end":642.32,"text":"If you now click another transcript line, the app keeps your edited draft instead of silently"},{"start":642.32,"end":647.76,"text":"overwriting it. Clear the question first when you truly want a new selection."},{"start":648.8833333333333,"end":651.5583333333333,"text":"Click Done to leave question editing."},{"start":651.5583333333333,"end":655.4983333333333,"text":"This is not Ask; the reviewed text remains local."},{"start":656.6166666666667,"end":660.8216666666666,"text":"Click Copy draft if you want to use the question somewhere else."},{"start":660.8216666666666,"end":666.0316666666666,"text":"In real use this writes to the Windows clipboard, outside capture protection."},{"start":666.0316666666666,"end":669.8316666666666,"text":"This demonstration uses an isolated clipboard sink."},{"start":670.95,"end":673.565,"text":"Click Setup slash details."},{"start":673.565,"end":679.93,"text":"Snapshot only is the safe local mode: it freezes your question without sending a model request."},{"start":681.0500000000001,"end":686.155,"text":"Click Freeze locally. The submitted snapshot is a separate copy."},{"start":686.155,"end":690.065,"text":"Later draft changes cannot rewrite that earlier snapshot."},{"start":691.1833333333334,"end":694.5483333333334,"text":"Freezing returns to the reading view automatically."},{"start":694.5483333333334,"end":700.3433333333334,"text":"You can reopen Setup slash details to inspect the provider notice and draft provenance."},{"start":700.3433333333334,"end":703.2233333333334,"text":"The snapshot and draft remain separate."},{"start":704.35,"end":708.35,"text":"Click Clear question, immediately to the right of Ask."},{"start":708.35,"end":714.55,"text":"It clears the draft, snapshot, answer, clarification, and previous-answer selection."},{"start":714.55,"end":718.185,"text":"It does not erase the meeting transcript or your notes."},{"start":719.3166666666667,"end":722.7766666666666,"text":"Click Choose source for the compact selection panel."},{"start":722.7766666666666,"end":726.7116666666667,"text":"This is an alternative to clicking the main transcript directly."},{"start":727.8166666666667,"end":731.4416666666667,"text":"Click Mic to show microphone segments in this chooser."},{"start":731.4416666666667,"end":733.6866666666667,"text":"Filtering changes what you browse;"},{"start":733.6866666666667,"end":735.9666666666667,"text":"it does not send a question."},{"start":737.0833333333334,"end":739.9833333333333,"text":"Click the microphone segment you want."},{"start":739.9833333333333,"end":745.0333333333333,"text":"Then use the explicit Use selected action to copy that selection into your draft."},{"start":746.1500000000001,"end":750.2800000000001,"text":"Click Use selected. The app creates the draft locally;"},{"start":750.2800000000001,"end":752.73,"text":"Ask remains a separate action."},{"start":753.85,"end":756.855,"text":"Open Choose source again and use All to browse both tracks."},{"start":756.855,"end":759.75,"text":"Computer filters to playback only."},{"start":759.75,"end":764.9599999999999,"text":"The source chooser is optional; direct transcript clicks are usually faster."},{"start":766.0833333333334,"end":771.4333333333333,"text":"Close the chooser and clear this sample question so we can move on to the answer workflow."},{"start":772.5500000000001,"end":778.075,"text":"Phantom Fudge supports an installed Agency provider, direct Copilot, or a separately configured"},{"start":778.075,"end":784.15,"text":"local model. Agency and ordinary Copilot can use remote model services."},{"start":784.15,"end":789.11,"text":"A local command-line process does not by itself mean offline inference."},{"start":790.2166666666667,"end":795.2566666666667,"text":"In the source workflow, use Initialize Answers with Provider Agency."},{"start":795.2566666666667,"end":798.5366666666666,"text":"Use the exact qualified Agency build shown here;"},{"start":798.5366666666666,"end":801.4116666666666,"text":"other versions fail until qualified."},{"start":801.4116666666666,"end":805.2366666666667,"text":"The helper writes non-secret settings and may build the app."},{"start":805.2366666666667,"end":808.5616666666666,"text":"It does not install Agency or sign you in."},{"start":808.5616666666666,"end":810.9216666666666,"text":"Then return and Reload setup."},{"start":812.0500000000001,"end":817.41,"text":"Direct Copilot requires a separately installed compatible CLI, with the supported versions"},{"start":817.41,"end":822.2900000000001,"text":"shown here. Choose Provider Copilot through the source helper."},{"start":822.2900000000001,"end":824.635,"text":"Connect explicitly starts sign-in;"},{"start":824.635,"end":827.64,"text":"do not trigger it casually during a meeting."},{"start":827.64,"end":832.5550000000001,"text":"This hosted route remains unqualified after an earlier failed smoke attempt."},{"start":833.6833333333334,"end":839.0233333333333,"text":"LocalModel needs both a compatible direct Copilot CLI and an already-running OpenAI-compatible"},{"start":839.0233333333333,"end":844.9533333333334,"text":"model server. Configure its real model identifier and loopback endpoint."},{"start":844.9533333333334,"end":850.3183333333334,"text":"There is no hosted fallback, but a local endpoint could itself proxy remotely, so"},{"start":850.3183333333334,"end":852.8383333333334,"text":"verify the server's behavior."},{"start":852.8383333333334,"end":856.1133333333333,"text":"No actual local model was qualified here."},{"start":857.2166666666667,"end":862.0616666666666,"text":"This is a source-checkout example, not an installed model promise."},{"start":862.0616666666666,"end":865.4366666666666,"text":"Replace the model and port with your real setup."},{"start":865.4366666666666,"end":870.1866666666666,"text":"The helper writes this user's answers dot JSON at the shown path."},{"start":870.1866666666666,"end":872.5166666666667,"text":"Installed packages omit the helper;"},{"start":872.5166666666667,"end":877.0916666666667,"text":"use the provider guide for that file's schema, then Reload setup."},{"start":878.2166666666667,"end":882.9766666666667,"text":"Click Setup slash details to inspect the mode and provider notice."},{"start":882.9766666666667,"end":885.5616666666666,"text":"This panel selects and reloads settings;"},{"start":885.5616666666666,"end":889.7366666666667,"text":"it is not an account, model, or executable-path editor."},{"start":889.7366666666667,"end":893.0416666666666,"text":"Read the data boundary before enabling a provider."},{"start":894.1500000000001,"end":898.73,"text":"After changing provider configuration, click Reload setup."},{"start":898.73,"end":902.375,"text":"Loading configuration does not submit your question."},{"start":902.375,"end":906.715,"text":"The real Agency path may prepare its transport in the background."},{"start":907.8166666666667,"end":913.2466666666667,"text":"For the remaining lessons, this isolated copy uses a sample provider instead of contacting"},{"start":913.2466666666667,"end":918.5016666666667,"text":"Agency. The application still runs its real question, streaming,"},{"start":918.5016666666667,"end":922.3016666666666,"text":"context, and clarification state changes."},{"start":923.4166666666667,"end":928.2316666666667,"text":"Click Snapshot only whenever you want to freeze questions without sending them."},{"start":928.2316666666667,"end":933.2766666666666,"text":"Changing provider mode resets previous-answer context and clarification."},{"start":934.3833333333333,"end":938.3433333333332,"text":"Click the configured-provider button to enable answers again."},{"start":938.3433333333332,"end":941.5883333333333,"text":"On a real Agency setup, wait for readiness;"},{"start":941.5883333333333,"end":946.7933333333333,"text":"if preparation fails, read the status rather than repeatedly pressing Ask."},{"start":947.9166666666667,"end":950.5766666666667,"text":"Close Setup slash details."},{"start":950.5766666666667,"end":954.3866666666667,"text":"The question reader is now ready for an explicit request."},{"start":955.5166666666668,"end":959.1466666666668,"text":"Click Type slash edit to enter a question directly."},{"start":959.1466666666668,"end":963.6016666666667,"text":"You do not need a transcript selection if you already know what to ask."},{"start":964.7166666666667,"end":968.0566666666666,"text":"Type a clear question with the constraints you want."},{"start":968.0566666666666,"end":973.3416666666667,"text":"Only this reviewed question is used, unless you explicitly enable a documented context"},{"start":973.3416666666667,"end":974.5416666666666,"text":"option."},{"start":975.6500000000001,"end":982.0500000000001,"text":"Click Ask provider. The app freezes the exact text and streams the answer into the reader."},{"start":982.0500000000001,"end":987.35,"text":"This sample response is scripted, not evidence of model quality or latency."},{"start":988.45,"end":991.78,"text":"Wait for the completed answer before relying on it."},{"start":991.78,"end":994.19,"text":"The answer is plain text."},{"start":994.19,"end":998.93,"text":"You remain responsible for checking accuracy and speaking in your own words."},{"start":1000.0500000000001,"end":1003.225,"text":"Drag the Size slider in the answer section."},{"start":1003.225,"end":1009.48,"text":"It changes the answer and interpretation font from eight to twenty-four, for this session only."},{"start":1009.48,"end":1012.735,"text":"It does not resize the transcript or notes."},{"start":1013.85,"end":1017.3299999999999,"text":"Click Copy answer to copy the displayed result."},{"start":1017.3299999999999,"end":1021.99,"text":"The Windows clipboard is not protected by the window's capture policy."},{"start":1021.99,"end":1025.6,"text":"This tutorial routes copying to an isolated sink."},{"start":1026.7166666666667,"end":1033.1916666666666,"text":"While Agency is preparing, use Cancel preparation, or Cancel prep in a narrow layout."},{"start":1033.1916666666666,"end":1039.2816666666668,"text":"Wait for cleanup. Use configured provider or Reload setup prepares it again."},{"start":1039.2816666666668,"end":1042.9766666666667,"text":"Cancelling preparation does not stop transcription."},{"start":1042.9766666666667,"end":1045.5566666666666,"text":"Preparation differs from a submitted answer;"},{"start":1045.5566666666666,"end":1048.5566666666666,"text":"neither guarantees a fixed response time."},{"start":1049.6833333333334,"end":1054.5483333333334,"text":"For a follow-up, click Previous answer immediately to the left of Ask."},{"start":1054.5483333333334,"end":1056.6283333333333,"text":"It is off by default."},{"start":1056.6283333333333,"end":1058.9533333333334,"text":"Turning it on does not send anything;"},{"start":1058.9533333333334,"end":1063.5733333333333,"text":"the next explicit Ask captures the completed answer currently displayed."},{"start":1064.6833333333334,"end":1067.2733333333333,"text":"Edit the question to your follow-up."},{"start":1067.2733333333333,"end":1072.8683333333333,"text":"Do not click Clear first: Clear would remove the answer you want to use as context."},{"start":1073.9833333333333,"end":1079.6983333333333,"text":"Click Ask provider. This request includes the new question and one immutable previous-answer"},{"start":1079.6983333333333,"end":1085.5783333333334,"text":"snapshot. It does not automatically include old questions, older answers,"},{"start":1085.5783333333334,"end":1088.0583333333334,"text":"notes, or the whole meeting."},{"start":1089.1833333333334,"end":1093.3633333333335,"text":"Open Setup slash details after the response completes."},{"start":1093.3633333333335,"end":1098.9583333333333,"text":"The previous-answer field shows the exact submitted context, not whatever happens to be displayed"},{"start":1098.9583333333333,"end":1100.0983333333334,"text":"later."},{"start":1101.2166666666667,"end":1106.7566666666667,"text":"Close details. After a successful follow-up, the option stays on,"},{"start":1106.7566666666667,"end":1110.8066666666666,"text":"but the next request uses only the newest completed answer."},{"start":1110.8066666666666,"end":1114.9416666666666,"text":"Failed, cancelled, and unfinished output is not eligible."},{"start":1116.05,"end":1119.81,"text":"Click Previous answer again for an unrelated question."},{"start":1119.81,"end":1122.29,"text":"It turns off without sending."},{"start":1122.29,"end":1126.02,"text":"Clear and provider changes also reset this selection."},{"start":1127.15,"end":1133.315,"text":"Click Clear question, then Done, to begin a separate example outside question-edit mode."},{"start":1133.315,"end":1138.71,"text":"This deliberately discards the previous Q slash A state while keeping the transcript."},{"start":1139.8166666666666,"end":1142.1116666666665,"text":"Check Clarify first."},{"start":1142.1116666666665,"end":1146.6316666666667,"text":"The first request will ask for an interpretation rather than a solution."},{"start":1146.6316666666667,"end":1149.9516666666666,"text":"Checking the box alone does not make a request."},{"start":1151.0833333333335,"end":1155.5283333333334,"text":"Click Type slash edit and write the question that needs clarification."},{"start":1155.5283333333334,"end":1157.9083333333335,"text":"Click Done when the wording is ready."},{"start":1159.25,"end":1161.5349999999999,"text":"Click Interpret question."},{"start":1161.5349999999999,"end":1165.7549999999999,"text":"The app locks the original draft and displays an interpretation."},{"start":1165.7549999999999,"end":1168.0249999999999,"text":"This is not the final answer."},{"start":1169.15,"end":1171.805,"text":"Read what the provider thinks you mean."},{"start":1171.805,"end":1175.615,"text":"If it is correct, use Yes, answer."},{"start":1175.615,"end":1179.63,"text":"If it is wrong or incomplete, type a correction instead."},{"start":1180.75,"end":1186.705,"text":"Copy interpretation copies what the provider thinks you mean, not a confirmed solution."},{"start":1186.705,"end":1192.1299999999999,"text":"Copy original preserves the original question rather than substituting the correction field."},{"start":1193.25,"end":1196.495,"text":"Click Type reply to enable the reply editor."},{"start":1196.495,"end":1200.53,"text":"A correction does not silently replace the original draft."},{"start":1201.65,"end":1204.025,"text":"Specify what was missing."},{"start":1204.025,"end":1208.595,"text":"Here we request a remote-audience example and three practical tips."},{"start":1208.595,"end":1213.93,"text":"Yes, answer is disabled while a correction is written, so it cannot silently discard"},{"start":1213.93,"end":1215.4550000000002,"text":"that correction."},{"start":1216.5833333333335,"end":1222.7433333333333,"text":"Click Send reply. This sends the correction with this question's clarification history."},{"start":1222.7433333333333,"end":1225.2883333333334,"text":"The app waits for another interpretation;"},{"start":1225.2883333333334,"end":1227.5333333333335,"text":"it does not auto-confirm."},{"start":1228.65,"end":1233.94,"text":"Once the revised interpretation is correct, click Yes, answer."},{"start":1233.94,"end":1239.68,"text":"Typing exact Yes and pressing Send reply also confirms, ignoring surrounding whitespace"},{"start":1239.68,"end":1246.3600000000001,"text":"and case. Yes, but followed by more text is a correction, not confirmation."},{"start":1247.4833333333333,"end":1249.7683333333332,"text":"The solution now appears."},{"start":1249.7683333333332,"end":1255.2983333333334,"text":"Previous answer, when enabled initially, stays pinned through clarification."},{"start":1255.2983333333334,"end":1261.0333333333333,"text":"After four interpretations, confirm the intended question or Clear to start over."},{"start":1261.0333333333333,"end":1267.1033333333332,"text":"Setup slash details shows the extra instruction and completed clarification exchanges."},{"start":1268.2166666666667,"end":1273.0766666666666,"text":"Uncheck Clarify first when you no longer need the interpretation step."},{"start":1273.0766666666666,"end":1275.8566666666666,"text":"The original question remains available."},{"start":1276.9833333333333,"end":1280.8383333333334,"text":"We will demonstrate a deliberately slow sample response."},{"start":1280.8383333333334,"end":1285.0283333333332,"text":"There is no real model request or network delay in this example."},{"start":1286.15,"end":1291.38,"text":"Click Ask provider. While a response is in progress, do not start another"},{"start":1291.38,"end":1293.77,"text":"request or switch providers."},{"start":1294.8833333333334,"end":1297.8733333333334,"text":"Click Cancel answer and wait for cleanup."},{"start":1297.8733333333334,"end":1302.8783333333333,"text":"Any copied partial result begins with Incomplete answer in square brackets."},{"start":1302.8783333333333,"end":1307.5833333333335,"text":"It is not a completed answer and cannot become previous-answer context."},{"start":1308.6833333333334,"end":1313.4733333333334,"text":"Click Clear question when you want to discard the cancelled result and begin again."},{"start":1313.4733333333334,"end":1316.5933333333332,"text":"This does not clear your meeting transcript."},{"start":1317.7166666666667,"end":1319.9916666666666,"text":"Read the provider status."},{"start":1319.9916666666666,"end":1326.4516666666666,"text":"Check configuration and authorization through the provider's documented setup, then Reload setup."},{"start":1326.4516666666666,"end":1331.6666666666667,"text":"Do not paste tokens into the question, and do not assume a failed local model will fall back"},{"start":1331.6666666666667,"end":1337.2816666666668,"text":"to the cloud. Snapshot only remains available for local question drafting."},{"start":1338.3833333333334,"end":1341.5833333333335,"text":"Click Notes to expand the speaker-note area."},{"start":1341.5833333333335,"end":1346.8233333333335,"text":"This closes Q slash A and cancels its answer or preparation, but leaves transcription"},{"start":1346.8233333333335,"end":1349.3233333333335,"text":"running and preserves the question."},{"start":1349.3233333333335,"end":1354.1433333333334,"text":"Entering global Notes Edit next is different: that stops audio too."},{"start":1355.25,"end":1357.76,"text":"Click the top-bar Edit button."},{"start":1357.76,"end":1363.3799999999999,"text":"Unlike question editing, global Notes Edit stops transcription and cancels answer or preparation"},{"start":1363.3799999999999,"end":1368.2549999999999,"text":"activity. It enables note typing and file operations."},{"start":1368.2549999999999,"end":1371.7849999999999,"text":"Control Alt E is the direct Notes Edit shortcut."},{"start":1372.9166666666667,"end":1375.6916666666666,"text":"Type plain-text notes in the editor."},{"start":1375.6916666666666,"end":1378.6266666666668,"text":"Keep prompts short enough to glance at."},{"start":1378.6266666666668,"end":1381.4566666666667,"text":"New notes are not automatically saved."},{"start":1382.5833333333335,"end":1387.8483333333334,"text":"With keyboard-control mode inactive, Notes Edit supports Control S, O,"},{"start":1387.8483333333334,"end":1391.8983333333335,"text":"N and F for save, open, new and find."},{"start":1391.8983333333335,"end":1396.8583333333333,"text":"Control Z undoes recent note edits, with a hundred undo units."},{"start":1396.8583333333333,"end":1400.0783333333334,"text":"New and a successful Open clear that history."},{"start":1400.0783333333334,"end":1404.0633333333335,"text":"Undo is not autosave or recovery of a discarded document."},{"start":1405.1833333333334,"end":1408.3733333333334,"text":"Click A plus to enlarge the notes text."},{"start":1408.3733333333334,"end":1411.8933333333334,"text":"This control is separate from the answer Size slider."},{"start":1413.0166666666667,"end":1416.2566666666667,"text":"Click A minus to reduce the notes font again."},{"start":1416.2566666666667,"end":1420.1866666666665,"text":"The notes control supports sizes from twelve to forty-two."},{"start":1421.3166666666666,"end":1426.6366666666665,"text":"Uncheck Wrap if you want long lines to remain on one line with horizontal scrolling."},{"start":1426.6366666666665,"end":1430.0516666666665,"text":"This affects notes, not the answer reader."},{"start":1431.1833333333334,"end":1435.0633333333333,"text":"Check Wrap again for a compact, glanceable note."},{"start":1435.0633333333333,"end":1438.1183333333333,"text":"Content is preserved when wrapping changes."},{"start":1439.25,"end":1442.18,"text":"Click Find to open the note search field."},{"start":1442.18,"end":1446.12,"text":"This search is separate from transcript search in keyboard mode."},{"start":1447.25,"end":1449.73,"text":"Type the word you want to find."},{"start":1449.73,"end":1452.1499999999999,"text":"Here we will search for example."},{"start":1453.25,"end":1456.1,"text":"Click Next to select the next match."},{"start":1456.1,"end":1459.0449999999998,"text":"The search wraps back to the beginning when needed."},{"start":1460.15,"end":1463,"text":"Click Close find when you are finished."},{"start":1463,"end":1466.66,"text":"Your note is still unsaved until you explicitly save it."},{"start":1467.7833333333333,"end":1474.0533333333333,"text":"Click Save. On the first save, choose a destination in the Windows file picker."},{"start":1474.0533333333333,"end":1480.0533333333333,"text":"The picker is omitted here; the real save operation writes only an isolated sample file."},{"start":1480.0533333333333,"end":1482.7183333333332,"text":"Saved locally confirms the write."},{"start":1483.8500000000001,"end":1489.69,"text":"Use Save as when you want another destination or need to resolve a file that changed outside the app."},{"start":1489.69,"end":1493.44,"text":"Do not overwrite a file without checking what it contains."},{"start":1494.55,"end":1498.105,"text":"Click Open and choose a UTF-eight text file."},{"start":1498.105,"end":1501.155,"text":"This demo opens an isolated example."},{"start":1501.155,"end":1506.8149999999998,"text":"The app accepts files up to one mebibyte and retains your current content if opening fails."},{"start":1507.9166666666667,"end":1511.3716666666667,"text":"Make an edit to see the unsaved-change safeguard."},{"start":1511.3716666666667,"end":1514.8766666666668,"text":"The status clearly says there are unsaved changes."},{"start":1515.9833333333333,"end":1522.1883333333333,"text":"Click New. Because the note is unsaved, an inline confirmation appears."},{"start":1522.1883333333333,"end":1525.9483333333333,"text":"Save notes, cancel, or explicitly discard;"},{"start":1525.9483333333333,"end":1528.9083333333333,"text":"do not treat closing the panel as a save."},{"start":1530.0166666666667,"end":1533.9516666666666,"text":"Click Cancel to keep the unsaved note and return to editing."},{"start":1535.0833333333335,"end":1541.0133333333335,"text":"Click New once more. We will deliberately discard only this throwaway sample draft."},{"start":1542.1166666666668,"end":1544.4816666666668,"text":"Click Discard and continue."},{"start":1544.4816666666668,"end":1546.8466666666668,"text":"The new blank note appears."},{"start":1546.8466666666668,"end":1552.0816666666667,"text":"This is a destructive choice for unsaved note text, not an undoable save."},{"start":1553.1833333333334,"end":1556.6183333333333,"text":"Click Present when you are ready to read rather than edit."},{"start":1556.6183333333333,"end":1558.8933333333334,"text":"The note becomes read-only."},{"start":1558.8933333333334,"end":1561.8483333333334,"text":"Audio does not automatically restart."},{"start":1562.95,"end":1565.595,"text":"Click Notes to collapse the area."},{"start":1565.595,"end":1569.895,"text":"Collapsing is just a layout action, not a save or delete."},{"start":1571.0166666666667,"end":1573.3616666666667,"text":"Click Edit before exporting."},{"start":1573.3616666666667,"end":1578.6716666666666,"text":"Export is intentionally disabled in presentation mode because native file dialogs are outside"},{"start":1578.6716666666666,"end":1580.5916666666667,"text":"capture assurance."},{"start":1581.7166666666667,"end":1585.3216666666667,"text":"Click Export and choose a text-file destination."},{"start":1585.3216666666667,"end":1588.3466666666666,"text":"The Windows picker is omitted in this demo."},{"start":1588.3466666666666,"end":1590.6466666666668,"text":"The transcript is saved as text;"},{"start":1590.6466666666668,"end":1593.0466666666666,"text":"no audio recording is written."},{"start":1594.15,"end":1597.035,"text":"Open Audio setup after export."},{"start":1597.035,"end":1602.4950000000001,"text":"Clear transcript is inside this panel, separate from the red Clear question button."},{"start":1603.6166666666668,"end":1608.9316666666668,"text":"Click Clear transcript after recording has stopped and the transcript has been exported."},{"start":1608.9316666666668,"end":1614.6566666666668,"text":"If it is still unsaved, the app refuses to clear it and asks you to export first."},{"start":1615.7833333333333,"end":1619.5683333333332,"text":"Click Done, then Present to leave file-edit mode."},{"start":1619.5683333333332,"end":1622.4233333333332,"text":"Nothing resumes recording automatically."},{"start":1623.55,"end":1626.8899999999999,"text":"Collapse Notes and show Q slash A again."},{"start":1626.8899999999999,"end":1631.0349999999999,"text":"We will load a fresh sample conversation for keyboard practice."},{"start":1632.15,"end":1635.4550000000002,"text":"The next lines are synthetic practice text."},{"start":1635.4550000000002,"end":1641.825,"text":"Keyboard controls let you select, review, and submit without moving a mouse around the window."},{"start":1642.95,"end":1646.41,"text":"Click Keys, or press Control Alt K."},{"start":1646.41,"end":1648.565,"text":"The strip says Control."},{"start":1648.565,"end":1651.565,"text":"Letters act as commands only in this local mode;"},{"start":1651.565,"end":1654.03,"text":"there is no global letter hook."},{"start":1654.03,"end":1658.56,"text":"From Control, I enters question or reply editing directly."},{"start":1659.6833333333334,"end":1664.6333333333334,"text":"Press F1, or question mark, for the on-screen key map."},{"start":1664.6333333333334,"end":1667.0083333333334,"text":"Escape returns to Control."},{"start":1668.1166666666668,"end":1672.0866666666668,"text":"Press Escape. The mode label returns to Control;"},{"start":1672.0866666666668,"end":1674.4966666666667,"text":"you have not submitted a question."},{"start":1675.6166666666668,"end":1678.1766666666667,"text":"Press V to enter Select mode."},{"start":1678.1766666666667,"end":1683.6366666666668,"text":"Use J and K, or the arrow keys, to move between transcript rows."},{"start":1683.6366666666668,"end":1686.5416666666667,"text":"Moving the cursor does not select a row."},{"start":1687.65,"end":1691.095,"text":"Press G twice to jump to the first available row."},{"start":1691.095,"end":1693.72,"text":"Shift G jumps to the latest row."},{"start":1693.72,"end":1696.57,"text":"Page keys move through larger lists."},{"start":1697.6833333333334,"end":1700.6183333333333,"text":"Press Space to select the highlighted row."},{"start":1700.6183333333333,"end":1703.2133333333334,"text":"Pressing it again deselects that row."},{"start":1704.3166666666666,"end":1708.6366666666665,"text":"Press J to move down, then Space to add the second row."},{"start":1708.6366666666665,"end":1711.6916666666666,"text":"The draft combines selected text locally."},{"start":1712.8166666666666,"end":1715.3616666666665,"text":"Press one to browse Mic rows."},{"start":1715.3616666666665,"end":1719.4766666666665,"text":"Two shows Computer, and three restores all sources."},{"start":1719.4766666666665,"end":1722.9516666666666,"text":"Existing selected rows are preserved when you filter."},{"start":1724.0833333333335,"end":1726.8033333333335,"text":"Press three to see all sources again."},{"start":1728.0833333333335,"end":1732.8733333333334,"text":"Press F3, or slash, to open transcript search."},{"start":1732.8733333333334,"end":1737.2883333333334,"text":"This is not the note Find feature, and it does not call a model."},{"start":1738.4166666666667,"end":1743.3066666666666,"text":"Type remote, then press Enter to find matching transcript text."},{"start":1743.3066666666666,"end":1749.2816666666668,"text":"To clear the filter later, open Search, erase its text, and press Enter."},{"start":1749.2816666666668,"end":1752.2566666666667,"text":"Escape from Search returns to Select."},{"start":1753.3833333333334,"end":1756.6783333333333,"text":"Press Enter from Select mode to move into Edit."},{"start":1756.6783333333333,"end":1759.9283333333333,"text":"That Enter only prepares the draft for review."},{"start":1759.9283333333333,"end":1764.4283333333333,"text":"Control Enter cannot bypass this review while you are still selecting."},{"start":1765.55,"end":1769.99,"text":"In Edit mode, letters are normal text and Enter adds a newline."},{"start":1769.99,"end":1772.895,"text":"Control Enter explicitly submits."},{"start":1772.895,"end":1777.5849999999998,"text":"Escape to Control before using modal F one help or F two commands."},{"start":1778.7166666666667,"end":1782.1016666666667,"text":"Press Control Enter to send the reviewed question."},{"start":1782.1016666666667,"end":1786.4516666666666,"text":"This uses the same snapshot and provider rules as clicking Ask."},{"start":1787.5833333333335,"end":1791.9633333333334,"text":"Wait for the answer, then press Escape to return to Control."},{"start":1791.9633333333334,"end":1794.9683333333335,"text":"Leaving Edit does not make another request."},{"start":1796.0833333333335,"end":1798.3883333333335,"text":"Press A to enter Read mode."},{"start":1798.3883333333335,"end":1802.0483333333334,"text":"J and K, arrows, and page keys move through the answer;"},{"start":1802.0483333333334,"end":1804.6083333333333,"text":"Home and End reach its boundaries."},{"start":1805.7166666666667,"end":1808.3766666666666,"text":"Press plus to enlarge the answer."},{"start":1808.3766666666666,"end":1813.2166666666667,"text":"Minus reduces it, within the same eight-to-twenty-four range as the slider."},{"start":1814.3166666666666,"end":1818.6516666666666,"text":"Press End to move to the end, then Home to return to the beginning."},{"start":1818.6516666666666,"end":1821.2166666666665,"text":"The text itself is unchanged."},{"start":1822.3166666666666,"end":1826.3016666666665,"text":"Press Escape to return to Control before choosing another mode."},{"start":1827.4166666666667,"end":1830.5466666666666,"text":"Press F2 to open the built-in command line."},{"start":1831.65,"end":1835.0800000000002,"text":"Type font sixteen for an exact answer size."},{"start":1836.1833333333334,"end":1839.0733333333333,"text":"Press Enter to execute this command."},{"start":1839.0733333333333,"end":1841.6483333333333,"text":"Read the status before moving on."},{"start":1842.75,"end":1845.8799999999999,"text":"Press F2 to open the built-in command line."},{"start":1846.9833333333333,"end":1852.4483333333333,"text":"Type context on to include the displayed completed answer on your next explicit Ask."},{"start":1853.55,"end":1856.4399999999998,"text":"Press Enter to execute this command."},{"start":1856.4399999999998,"end":1859.0149999999999,"text":"Read the status before moving on."},{"start":1860.1166666666668,"end":1863.2466666666667,"text":"Press F2 to open the built-in command line."},{"start":1864.3500000000001,"end":1867.635,"text":"Type context off for an unrelated question."},{"start":1868.75,"end":1871.6399999999999,"text":"Press Enter to execute this command."},{"start":1871.6399999999999,"end":1874.215,"text":"Read the status before moving on."},{"start":1875.3166666666666,"end":1878.4466666666665,"text":"Press F2 to open the built-in command line."},{"start":1879.55,"end":1883.0949999999998,"text":"Type devices to open keyboard device selection."},{"start":1883.0949999999998,"end":1887.125,"text":"First stop transcription and finish or cancel any answer."},{"start":1888.25,"end":1891.1399999999999,"text":"Press Enter to execute this command."},{"start":1891.1399999999999,"end":1893.715,"text":"Read the status before moving on."},{"start":1894.8166666666666,"end":1898.9516666666666,"text":"In Devices mode, arrow keys move the highlighted card."},{"start":1898.9516666666666,"end":1903.3666666666666,"text":"Space selects it. Tab switches between Computer and Mic;"},{"start":1903.3666666666666,"end":1907.5266666666666,"text":"left and right brackets change pages when more devices exist."},{"start":1908.65,"end":1912.625,"text":"Press Escape to close device setup and return to Control."},{"start":1913.75,"end":1916.8799999999999,"text":"Press F2 to open the built-in command line."},{"start":1917.9833333333333,"end":1921.9733333333334,"text":"Type theme light to switch the visual theme without using the pointer."},{"start":1923.0833333333335,"end":1925.9733333333334,"text":"Press Enter to execute this command."},{"start":1925.9733333333334,"end":1928.5483333333334,"text":"Read the status before moving on."},{"start":1929.65,"end":1932.78,"text":"Press F2 to open the built-in command line."},{"start":1933.8833333333334,"end":1937.8933333333334,"text":"Type opacity eighty-five to set background tint directly."},{"start":1939.0166666666667,"end":1941.9066666666665,"text":"Press Enter to execute this command."},{"start":1941.9066666666665,"end":1944.4816666666666,"text":"Read the status before moving on."},{"start":1945.5833333333335,"end":1948.7133333333334,"text":"Press F2 to open the built-in command line."},{"start":1949.8166666666666,"end":1952.9966666666667,"text":"Type theme dark to return to Deep Sea Foam."},{"start":1954.2166666666667,"end":1957.1066666666666,"text":"Press Enter to execute this command."},{"start":1957.1066666666666,"end":1959.6816666666666,"text":"Read the status before moving on."},{"start":1960.7833333333333,"end":1963.2083333333333,"text":"Press F2 and type font."},{"start":1963.2083333333333,"end":1965.8983333333333,"text":"Tab can complete a matching built-in command;"},{"start":1965.8983333333333,"end":1968.7283333333332,"text":"Escape cancels without executing it."},{"start":1969.8500000000001,"end":1973.855,"text":"Press Escape to leave this completed suggestion without running it."},{"start":1974.9833333333333,"end":1980.7283333333332,"text":"Commands also cover start, stop, source Mic or Computer or Both, clarify"},{"start":1980.7283333333332,"end":1986.6233333333332,"text":"on or off, confirm, copy question, copy answer, clear question,"},{"start":1986.6233333333332,"end":1990.6283333333333,"text":"cancel, ask, mask, and help."},{"start":1990.6283333333333,"end":1995.7783333333332,"text":"Each command uses the same guarded action as the corresponding interface control."},{"start":1995.7783333333332,"end":1997.6033333333332,"text":"This is not a shell."},{"start":1998.7166666666667,"end":2004.4816666666666,"text":"Save the exact three-field UTF-eight JSON shown here as keyboard dot JSON,"},{"start":2004.4816666666666,"end":2007.1116666666667,"text":"then restart after saving work."},{"start":2007.1116666666667,"end":2009.5766666666666,"text":"Control Alt stays fixed."},{"start":2009.5766666666666,"end":2014.0516666666667,"text":"Enabled false disables global activation, not Keys."},{"start":2014.0516666666667,"end":2018.2366666666667,"text":"Invalid settings or a shortcut conflict leave Keys available."},{"start":2018.2366666666667,"end":2022.0116666666665,"text":"Use your configured activation key rather than assuming K."},{"start":2023.1166666666668,"end":2026.6166666666668,"text":"Press Escape from Control to leave keyboard mode."},{"start":2026.6166666666668,"end":2030.6116666666667,"text":"Returning focus to the earlier application is best-effort."},{"start":2030.6116666666667,"end":2033.9766666666667,"text":"Switching applications disarms the controller."},{"start":2033.9766666666667,"end":2038.7816666666668,"text":"Use Keys or your configured Control Alt activation chord to enter again."},{"start":2039.8833333333334,"end":2042.7033333333334,"text":"Click the book icon at the top left."},{"start":2042.7033333333334,"end":2048.5783333333334,"text":"The workspace is replaced by Notepad is ready, with the same icon available to restore it."},{"start":2049.683333333333,"end":2052.758333333333,"text":"The cover changes what the window displays."},{"start":2052.758333333333,"end":2056.278333333333,"text":"Transcription and answers can continue underneath it."},{"start":2056.278333333333,"end":2062.2433333333333,"text":"It does not provide universal invisibility, erase data, or hide the process from Windows."},{"start":2063.35,"end":2066.86,"text":"Click the book icon again to restore the workspace."},{"start":2066.86,"end":2070.415,"text":"The current question, answer, and layout return."},{"start":2071.5166666666664,"end":2075.0616666666665,"text":"Enter keyboard control with Control Alt K, then press M."},{"start":2075.0616666666665,"end":2078.5116666666668,"text":"Masking disarms keyboard mode and shows the cover."},{"start":2079.6166666666663,"end":2084.4766666666665,"text":"Press Control Alt K again to restore the workspace and enter Control mode."},{"start":2084.4766666666665,"end":2088.1016666666665,"text":"This is useful when you do not want to reach for the pointer."},{"start":2089.2166666666667,"end":2093.621666666667,"text":"Press Escape to leave keyboard control before the next pointer action."},{"start":2094.75,"end":2099.9700000000003,"text":"Click Hide. Unlike Cover, it hides the window, stops transcription, and"},{"start":2099.9700000000003,"end":2103.15,"text":"cancels answer or preparation activity."},{"start":2103.15,"end":2105.9950000000003,"text":"The blank stage shows the hidden window."},{"start":2105.9950000000003,"end":2110.4300000000003,"text":"Reveal it when ready, then start transcription again explicitly."},{"start":2111.5499999999997,"end":2115.12,"text":"Press Control Alt Space to reveal the window again."},{"start":2115.12,"end":2118.2149999999997,"text":"Relaunching the app is another recovery route."},{"start":2118.2149999999997,"end":2122.14,"text":"Hiding and recovery do not automatically resume recording."},{"start":2123.25,"end":2129.9100000000003,"text":"Click Diagnostics to reload diagnostic settings and open the local log folder outside window protection."},{"start":2129.9100000000003,"end":2135.57,"text":"Default logs contain timing and error metadata, not audio or text bodies."},{"start":2135.57,"end":2138.7000000000003,"text":"Text logging is a separate retention choice."},{"start":2139.8166666666666,"end":2143.5316666666668,"text":"Run these diagnostic helpers from the source checkout."},{"start":2143.5316666666668,"end":2146.0916666666667,"text":"Installed packages omit them."},{"start":2146.0916666666667,"end":2150.8816666666667,"text":"After changing the mode, click Diagnostics or restart to apply it."},{"start":2150.8816666666667,"end":2155.931666666667,"text":"Export stays local and excludes text unless Include Text is requested."},{"start":2155.931666666667,"end":2160.576666666667,"text":"Clearing the interface does not erase old logs or provider retention."},{"start":2161.683333333333,"end":2168.133333333333,"text":"Confirm the meeting plays through the selected Computer device, and that Mic is enabled only when intended."},{"start":2168.133333333333,"end":2171.328333333333,"text":"Check Windows microphone permission if needed."},{"start":2171.328333333333,"end":2174.183333333333,"text":"Stop before refreshing devices."},{"start":2174.183333333333,"end":2179.648333333333,"text":"If the service or token is missing, use the documented launcher and local service setup;"},{"start":2179.648333333333,"end":2182.4083333333333,"text":"do not paste a secret into notes."},{"start":2183.5166666666664,"end":2188.991666666667,"text":"Before relying on capture exclusion, test your exact sharing mode with a recipient and harmless"},{"start":2188.991666666667,"end":2195.4216666666666,"text":"text. A successful Windows protection request is not proof of what an audience sees."},{"start":2195.4216666666666,"end":2201.0116666666668,"text":"Native dialogs, files, clipboard history, accessibility, cameras, and unsupported"},{"start":2201.0116666666668,"end":2204.1666666666665,"text":"capture paths remain separate boundaries."},{"start":2205.2833333333333,"end":2210.5783333333334,"text":"Click Details in the status area to read the capture limitation in the application."},{"start":2210.5783333333334,"end":2214.5233333333335,"text":"Keep this distinction in mind even when the window looks quiet."},{"start":2215.6499999999996,"end":2219.355,"text":"Click Details again to return to the compact status."},{"start":2220.483333333333,"end":2226.3883333333333,"text":"Click X to exit. If notes, transcript, or question text remain unsaved,"},{"start":2226.3883333333333,"end":2230.3333333333335,"text":"the inline confirmation gives you a chance to preserve them."},{"start":2230.3333333333335,"end":2232.9183333333335,"text":"Copy question text before discarding;"},{"start":2232.9183333333335,"end":2235.963333333333,"text":"a note save is not a transcript export."},{"start":2237.083333333333,"end":2240.4733333333334,"text":"Click Cancel to keep the app and current content."},{"start":2240.4733333333334,"end":2246.063333333333,"text":"The exit attempt already stopped transcription and provider work before this confirmation."},{"start":2246.063333333333,"end":2248.528333333333,"text":"Cancel does not resume them."},{"start":2248.528333333333,"end":2255.083333333333,"text":"Save, export or copy what you need, then restart transcription explicitly if continuing."},{"start":2256.183333333333,"end":2261.5133333333333,"text":"For a normal session: check your sharing path, choose the correct devices, press"},{"start":2261.5133333333333,"end":2266.478333333333,"text":"Start, select and review the question, then explicitly Ask."},{"start":2266.478333333333,"end":2272.123333333333,"text":"Use Previous answer for a follow-up, and Clarify first when wording is unclear."},{"start":2272.123333333333,"end":2277.313333333333,"text":"At the end, Stop, save or export what you need, and exit."},{"start":2278.4166666666665,"end":2284.6766666666667,"text":"You have now seen the interface, optional provider setup, transcript and notes workflows,"},{"start":2284.6766666666667,"end":2290.491666666667,"text":"follow-up context, clarification, keyboard modes, and recovery."},{"start":2290.491666666667,"end":2295.9416666666666,"text":"The chapter player and searchable transcript let you revisit any step without watching the whole tutorial"},{"start":2295.9416666666666,"end":2297.1116666666667,"text":"again."}]};
